function cx(...args) {
  return args
    .filter(Boolean)
    .map((a) => (typeof a === 'object' ? Object.keys(a).filter((k) => a[k]).join(' ') : a))
    .filter(Boolean)
    .join(' ');
}

function cx(...args) {
  const out = [];
  const walk = (a) => {
    if (!a) return;
    if (Array.isArray(a)) a.forEach(walk);
    else if (typeof a === 'object') Object.keys(a).forEach((k) => a[k] && out.push(k));
    else out.push(a);
  };
  args.forEach(walk);
  return out.join(' ');
}

function merge(classes) {
  const list = classes.split(/\s+/).filter(Boolean);
  const key = (c) => /^(p|m|w)-/.exec(c)?.[1] ?? c;
  return list.filter((c, i) => !list.slice(i + 1).some((n) => key(n) === key(c))).join(' ');
}

