function merge(classes) {
  const list = classes.split(' ');
  const key = (c) => {
    const parts = c.split(':');
    const base = parts.pop();
    return parts.join(':') + '|' + (/^p-/.test(base) ? 'p' : base);
  };
  return list.filter((c, i) => !list.slice(i + 1).some((n) => key(n) === key(c))).join(' ');
}

function merge(classes) {
  const list = classes.split(' ');
  const group = (c) => c.slice(0, c.indexOf('-'));
  const beats = (later, earlier) =>
    group(later) === group(earlier) || (group(later) === 'p' && ['px', 'py'].includes(group(earlier)));
  return list.filter((c, i) => !list.slice(i + 1).some((n) => beats(n, c))).join(' ');
}

