function cva(base, { variants, defaults = {} }) {
  return (props = {}) => {
    const classes = Object.keys(variants).map((name) => variants[name][props[name] ?? defaults[name]]);
    return [base, ...classes].filter(Boolean).join(' ');
  };
}

