function createDialog({ onOpenChange }) {
  let open = false;
  return {
    set(next) {
      if (next === open) return;
      open = next;
      onOpenChange(next);
    },
  };
}

function onKey(state, key) {
  return state.open && key === 'Escape' ? { ...state, open: false } : state;
}

function nextFocus(index, count, shift) {
  return (index + (shift ? -1 : 1) + count) % count;
}

function render(type, props, asChild) {
  if (!asChild) return { type, props };
  const { children, ...rest } = props;
  return { type: children.type, props: { ...rest, ...children.props } };
}

function compose(own, outer) {
  return (event) => {
    outer?.(event);
    if (!event.defaultPrevented) own(event);
  };
}

function createIds(prefix) {
