function modules(file, names) {
  const base = file.replace('.module.css', '');
  return Object.fromEntries(names.map((n) => [n, `${base}_${n}`]));
}

function compose(styles, rules) {
  const out = { ...styles };
  for (const [name, from] of Object.entries(rules)) out[name] = `${styles[from]} ${styles[name]}`;
  return out;
}

function strict(styles) {
  return new Proxy(styles, {
    get(target, key) {
      if (!Object.hasOwn(target, key)) throw new Error('Klass yo\'q: ' + String(key));
      return target[key];
    },
  });
}

