function scopeCss(css, prefix) {
  return css.replace(/:global\(\.([\w-]+)\)|\.([a-zA-Z][\w-]*)/g, (m, global, local) =>
    global ? '.' + global : `.${prefix}_${local}`);
}

function styled(strings, ...fns) {
  return (props = {}) =>
    strings.reduce((out, s, i) => {
      const v = fns[i - 1];
      return out + (typeof v === 'function' ? v(props) : v ?? '') + s;
    });
}

