function createSheet() {
  const rules = new Map();
  return {
    add(css) {
      if (!rules.has(css)) rules.set(css, `css-${rules.size + 1}`);
      return rules.get(css);
    },
    size: () => rules.size,
  };
}

function toCss(obj) {
  const unitless = ['opacity', 'zIndex'];
  return Object.entries(obj)
    .map(([k, v]) => {
      const name = k.replace(/[A-Z]/g, (c) => '-' + c.toLowerCase());
      const value = typeof v === 'number' && !unitless.includes(k) ? v + 'px' : v;
      return `${name}:${value};`;
    })
    .join('');
}

function pick({ rsc, dynamic }) {
  if (rsc) return 'modules';
  return dynamic ? 'variables' : 'utility';
}
